package com.primehr.performancemanagement.application;import com.primehr.integration.humanresource.*;import com.primehr.performancemanagement.api.PerformanceManagementTeamDtos.MemberInput;import org.springframework.stereotype.Service;import java.util.*;
@Service public class PmtMemberEligibilityService{private final HumanResourceEmployeeDirectoryClient directory;private final HumanResourceAssessmentSubjectClient employment;public PmtMemberEligibilityService(HumanResourceEmployeeDirectoryClient d,HumanResourceAssessmentSubjectClient e){directory=d;employment=e;}public List<EligibleMember>validate(List<MemberInput> members,String token){List<EligibleMember>result=new ArrayList<>();for(MemberInput input:members){HumanResourceEmployeeDirectoryEntry entry=directory.require(input.employeeNo(),token);HumanResourceAssessmentSubject active=employment.get(entry.employeeId(),token);if(!active.employeeNo().equalsIgnoreCase(input.employeeNo()))throw new HumanResourceDependencyException("HumanResource active-employment identity does not match",null);result.add(new EligibleMember(active.employeeId(),active.employeeNo(),active.displayName(),active.jobPositionId(),active.plantillaId()));}return result;}public record EligibleMember(Long employeeId,String employeeNo,String displayName,Long jobPositionId,Long plantillaId){}}
